import{z as n,x as o,o as e,c as s,q as B,j as V,D as a,d as r,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"XVA 的联动","description":"","frontmatter":{"title":"XVA 的联动","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc-xva-linkage.md","filePath":"quant/rc-xva-linkage.md","lastUpdated":1791413859000}'),D={name:"quant/rc-xva-linkage.md"};function C(p,A,d,F,m,h){const t=o("Mermaid");return e(),s("div",null,[A[2]||(A[2]=B('<h1 id="xva-的联动" tabindex="-1">XVA 的联动 <a class="header-anchor" href="#xva-的联动" aria-label="Permalink to &quot;XVA 的联动&quot;">​</a></h1><div class="epigraph"><p>XVA 不是一个价，而是同一份合同在信用、资金与资本约束下的一组影子价格；五个部门各算各的账，重复计算就从合同的缝隙里长出来。</p><footer>—— 据 Gregory, *The xVA Challenge*, Wiley, 2015 整理</footer></div><p><a href="/quant/rc-collateral-funding">上一课</a>把抵押品与资金链接进了折现曲线。本课把这些成本按科目归位：CVA 对手信用、DVA 自身信用、FVA 资金、MVA 初始保证金、KVA 资本，并回答真正难的问题——它们如何联动、哪些组合是重复计算、哪些争议只是定义之争。暴露剖面的构造已在 <a href="/quant/cva-exposure-profile">CVA 暴露剖面 EPE</a> 与<a href="/quant/xva-bridge">到 XVA 的桥</a>讲过，本课默认你持有那套工具，只谈联动。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一笔无抵押互换的公允价值不再等于风险中性现值。对手违约的期望损失</p> \\[\\mathrm{CVA}=\\mathrm{LGD}\\int_0^T \\mathrm{EE}(t)\\,d\\mathrm{PD}(t) \\]<p>取自暴露剖面；自身违约给出对称的 DVA（见<a href="/quant/dva-own-credit">DVA 与自身信用</a>）；未抵押 profile 占用的资金给 FVA（见<a href="/quant/fva-funding">FVA 与资金成本</a>）；初始保证金在保证金期内给 MVA；监管资本占用的成本是 KVA。缺口不在五个公式各自的存在性，而在它们的和：同一份 profile 被几个科目同时引用，谁减谁、谁重复，直接决定报价里加多少、对冲几份。</p><p><span class="marginnote">五个字母账各管一件事：CVA 是对手倒了你亏的期望损失；DVA 是你倒了对方赚的（自己的「违约也有价值」）；FVA 是未抵押头寸占用的资金费；MVA 是押初始保证金的成本；KVA 是资本占用费。同一份合同在五种约束下的影子价格，加总才是真实报价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>联动从合同条款开始：CSA 决定抵押门槛、独立金额与触发器，从而决定 profile 里「已抵押、未抵押、过度抵押」三段的划分。CVA 只对未抵押段收；过度抵押段是负债，进 FVA 的收益侧；初始保证金押出的部分不受净额结算保护，单独进 MVA。一套联合模拟同时产出 EE、PFE 与资金 profile，各科目从中各取所需——这是避免重复计算的机制基础：科目可以多，profile 只有一份。错向风险改的是联合分布而不是系数：暴露大的时候对手 PD 也大的合同（例如卖信用保护给高杠杆对手），用独立的 PD 与市场因子模拟会系统性低估 CVA，处理见<a href="/quant/rates-credit-hybrid">利率-信用混合定价</a>。对冲侧：CVA 台用指数 CDS 对冲利差 beta，残差的单名 gamma 与基差是新账本——对冲不消灭风险，只改写风险的形式。</p><p><span class="marginnote">数字直觉：若某合同五年内平均暴露 EE 约 200 万，对手年违约率 1%、回收四成，粗算 \\(\\mathrm{CVA}\\approx 200\\text{ 万}\\times 1\\%\\times 60\\%\\times 5\\text{ 年}\\approx 6\\) 万。暴露、违约率、LGD 三者相乘再沿时间积分，就是 CVA 的骨架。</span></p>',11)),(e(),V(l,null,{default:a(()=>[i(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20CSA%5B%22CSA%20%E6%9D%A1%E6%AC%BE%22%5D%20--%3E%20PROF%5B%22%E5%94%AF%E4%B8%80%E4%B8%80%E4%BB%BD%E6%9A%B4%E9%9C%B2%E4%B8%8E%E8%B5%84%E9%87%91%20profile%22%5D%0A%20%20PROF%20--%3E%20CVA%5B%22CVA%EF%BC%9A%E6%9C%AA%E6%8A%B5%E6%8A%BC%E6%AE%B5%22%5D%0A%20%20PROF%20--%3E%20FVA%5B%22FVA%EF%BC%9A%E8%B5%84%E9%87%91%E7%BC%BA%E5%8F%A3%E4%B8%8E%E8%BF%87%E5%BA%A6%E6%8A%B5%E6%8A%BC%22%5D%0A%20%20PROF%20--%3E%20MVA%5B%22MVA%EF%BC%9A%E5%88%9D%E5%A7%8B%E4%BF%9D%E8%AF%81%E9%87%91%E6%9C%9F%22%5D%0A%20%20PROF%20--%3E%20KVA%5B%22KVA%EF%BC%9A%E8%B5%84%E6%9C%AC%E5%8D%A0%E7%94%A8%22%5D%0A%20%20DVA%5B%22DVA%EF%BC%9A%E8%87%AA%E8%BA%AB%E8%BF%9D%E7%BA%A6%22%5D%20--%3E%20SUM%5B%22%E5%90%88%E8%AE%A1%E8%BF%9B%E6%8A%A5%E4%BB%B7%EF%BC%8C%E9%80%90%E9%A1%B9%E6%9F%A5%E9%87%8D%E5%A4%8D%22%5D%0A%20%20CVA%20--%3E%20SUM%0A%20%20FVA%20--%3E%20SUM%0A%20%20MVA%20--%3E%20SUM%0A%20%20KVA%20--%3E%20SUM%0A"})]),fallback:a(()=>[...A[0]||(A[0]=[r(" Loading... ",-1)])]),_:1})),A[3]||(A[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),A[4]||(A[4]=E("p",null,"重复计算最爱长在两处。其一：抵押品已经在 EE 里降低了暴露，若资金成本再对同一笔抵押品全额计一次 FVA，同一块钱被算两次——正确口径是只对净暴露的资金缺口计。其二：DVA 与 FVA 的争论是定义之争的两半：DVA 把自身违约当成对方的收益，会计上确认，经济上能否实现取决于自己能否活到那一天；FVA 若按对称的资金成本计，已隐含自身信用的一部分，两笔全额相加就会重叠。KVA 与下一课的监管资本衔接：\\(\\mathrm{KVA}=\\int \\kappa\\,\\mathrm{EC}(t)\\,dt\\)，经济资本与监管资本在这里分家——定价用哪个，取决于股东最终按哪个拿回报。XVA 的数是一组模型输出的差：profile 的网格、保证金期的假设、错向的设定各动一格，五个科目一起动。",-1)),A[5]||(A[5]=E("p",null,[E("span",{class:"marginnote"},"Gregory 的分类至今是行业标准词汇：CVA、DVA、FVA、MVA、KVA 各有明确的合同来源；行业争论从来不在「要不要算」，而在「哪两对不能同时全额算」——CVA 与 DVA、FVA 与 DVA 是最常打架的两对，报价单上必须写口径。")],-1)),(e(),V(l,null,{default:a(()=>[i(t,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20COL%5B%22%E6%8A%B5%E6%8A%BC%E5%93%81%E5%B7%B2%E5%9C%A8%20EE%20%E9%87%8C%E9%99%8D%E4%BD%8E%E6%9A%B4%E9%9C%B2%22%5D%20--%3E%20DBL%5B%22%E5%86%8D%E5%AF%B9%E5%90%8C%E4%B8%80%E7%AC%94%E5%85%A8%E9%A2%9D%E8%AE%A1%20FVA%22%5D%0A%20%20DBL%20--%3E%20TWICE%5B%22%E5%90%8C%E4%B8%80%E5%9D%97%E9%92%B1%E8%A2%AB%E7%AE%97%E4%B8%A4%E6%AC%A1%22%5D%0A%20%20FIX1%5B%22%E4%BF%AE%E6%AD%A3%EF%BC%9AFVA%20%E5%8F%AA%E5%AF%B9%E5%87%80%E6%9A%B4%E9%9C%B2%E7%9A%84%E8%B5%84%E9%87%91%E7%BC%BA%E5%8F%A3%E8%AE%A1%22%5D%0A%20%20DVA%5B%22DVA%20%E5%85%A8%E9%A2%9D%E7%A1%AE%E8%AE%A4%22%5D%20--%3E%20OVL%5B%22%E4%B8%8E%E5%AF%B9%E7%A7%B0%E8%AE%A1%E7%9A%84%20FVA%20%E9%87%8D%E5%8F%A0%22%5D%0A%20%20OVL%20--%3E%20FIX2%5B%22%E4%BF%AE%E6%AD%A3%EF%BC%9A%E4%B8%A4%E5%AF%B9%E9%87%8D%E5%8F%A0%E5%8F%AA%E5%85%A8%E9%A2%9D%E7%AE%97%E5%85%B6%E4%B8%80%E6%88%96%E6%89%93%E6%8A%98%22%5D%0A%20%20KVA%5B%22KVA%EF%BC%9Akappa%20%E4%B9%98%E7%BB%8F%E6%B5%8E%E8%B5%84%E6%9C%AC%20EC%22%5D%20--%3E%20SPLIT%5B%22%E4%B8%8E%E7%9B%91%E7%AE%A1%E8%B5%84%E6%9C%AC%E5%88%86%E5%AE%B6%EF%BC%8C%E6%8C%89%E8%82%A1%E4%B8%9C%E5%9B%9E%E6%8A%A5%E5%8F%A3%E5%BE%84%E5%AE%9A%22%5D%0A"})]),fallback:a(()=>[...A[1]||(A[1]=[r(" Loading... ",-1)])]),_:1})),A[6]||(A[6]=B('<p><span class="marginnote">常见误区：把 DVA 当成已到手的收益。自身信用恶化时 DVA 上升、账面利润变好——可那恰恰是因为你更可能赖账了。DVA 只有在你活到那一天、真的少还钱时才兑现；机构倒下时，账面 DVA 会随它一起消失。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不谈会计口径（IFRS 13 的公允价值层级、自用与交易性持仓的 DVA 处理）与对冲会计。XVA 的模型治理必须按联动设计：单独验证每个科目，会漏掉它们共享的假设——这正是「联动」作为一课的理由。报价上，XVA 不是价外的运输成本，它改变对哪些客户、哪些合同做生意的边际，穿透到限额与资本配置，即下一课。最后，KVA 是否属于「价格」仍有学派分歧：把不可对冲的资本成本计入报价是管理决策，不是无套利推论——写清楚口径，比选边更重要。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五个 XVA 共享一份由 CSA 决定的 profile，重复计算的检查点是「同一笔钱别算两次」。</li><li>CVA 与 DVA、FVA 与 DVA 的重叠是定义之争，报价口径必须写明。</li><li>错向风险进联合分布，不进系数。</li><li>XVA 的治理按联动设计，不能分科目单独验证；KVA 进不进价格是管理决策，写明口径。</li><li>出处：Gregory, <em>The xVA Challenge</em>, 2015；暴露剖面与混合定价见本栏 cva-exposure-profile、rates-credit-hybrid 两课。</li></ul>',5))])}const c=n(D,[["render",C]]);export{u as __pageData,c as default};
